// Process sync update request
const syncData = $input.first().json;
const { 
  clientId,
  sessionId,
  dataType, // 'character', 'scene', 'world', 'campaign'
  entityId,
  updateData,
  timestamp,
  priority = 'normal', // 'low', 'normal', 'high', 'critical'
  conflictResolution = 'timestamp' // 'timestamp', 'manual', 'merge'
} = syncData;

// Validate required fields
if (!clientId || !sessionId || !dataType || !entityId || !updateData) {
  throw new Error('Missing required fields: clientId, sessionId, dataType, entityId, updateData');
}

// Generate update ID if not provided
const updateId = syncData.updateId || `update_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`;

// Prepare sync operation data
const syncOperation = {
  updateId,
  clientId,
  sessionId,
  dataType,
  entityId,
  updateData,
  timestamp: timestamp || new Date().toISOString(),
  priority,
  conflictResolution,
  status: 'pending',
  metadata: {
    processedBy: 'real-time-sync-workflow',
    version: '1.0'
  }
};

return { json: syncOperation };

// Check for conflicts and apply resolution strategy
const syncData = $input.first().json;
const { updateId, dataType, entityId, conflictResolution, timestamp } = syncData;

// Get existing updates for the same entity
let existingUpdates = [];
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  existingUpdates = $input[1].json.values.filter(row => 
    row[2] === dataType && row[3] === entityId && row[6] !== 'resolved'
  ).map(row => ({
    updateId: row[0],
    clientId: row[1],
    dataType: row[2],
    entityId: row[3],
    updateData: JSON.parse(row[4] || '{}'),
    timestamp: row[5],
    status: row[6]
  }));
}

// Detect conflicts
const conflicts = [];
const currentTime = new Date(timestamp);

existingUpdates.forEach(existing => {
  const existingTime = new Date(existing.timestamp);
  const timeDiff = Math.abs(currentTime - existingTime);

  // Consider updates within 5 seconds as potentially conflicting
  if (timeDiff < 5000 && existing.updateId !== updateId) {
    conflicts.push({
      existingUpdate: existing,
      conflictType: 'simultaneous_update',
      timeDifference: timeDiff
    });
  }

  // Check for data-level conflicts
  const dataConflict = detectDataConflict(syncData.updateData, existing.updateData);
  if (dataConflict.hasConflict) {
    conflicts.push({
      existingUpdate: existing,
      conflictType: 'data_conflict',
      details: dataConflict.details
    });
  }
});

function detectDataConflict(newData, existingData) {
  const conflicts = [];

  // Check for conflicting field values
  for (const key in newData) {
    if (existingData.hasOwnProperty(key) && newData[key] !== existingData[key]) {
      // Some fields are expected to change frequently
      const nonConflictingFields = ['lastUpdated', 'timestamp', 'metadata'];
      if (!nonConflictingFields.includes(key)) {
        conflicts.push({
          field: key,
          newValue: newData[key],
          existingValue: existingData[key]
        });
      }
    }
  }

  return {
    hasConflict: conflicts.length > 0,
    details: conflicts
  };
}

// Apply conflict resolution
let resolvedData = syncData.updateData;
let resolutionLog = [];

if (conflicts.length > 0) {
  resolutionLog.push(`Detected ${conflicts.length} conflicts for ${dataType}:${entityId}`);

  switch (conflictResolution) {
    case 'timestamp':
      // Use the most recent update
      const sortedByTime = [syncData, ...conflicts.map(c => c.existingUpdate)]
        .sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

      if (sortedByTime[0].updateId === updateId) {
        resolutionLog.push('Update wins by timestamp (most recent)');
        // Keep our data as resolved
      } else {
        resolutionLog.push(`Update rejected - newer update exists: ${sortedByTime[0].updateId}`);
        // Use the newer data
        resolvedData = sortedByTime[0].updateData;
      }
      break;

    case 'merge':
      // Attempt to merge non-conflicting fields
      conflicts.forEach(conflict => {
        if (conflict.conflictType === 'data_conflict') {
          conflict.details.forEach(fieldConflict => {
            // For numeric fields, use the higher value (e.g., HP, XP)
            if (typeof fieldConflict.newValue === 'number' && typeof fieldConflict.existingValue === 'number') {
              if (fieldConflict.newValue > fieldConflict.existingValue) {
                resolutionLog.push(`Merged numeric field ${fieldConflict.field}: kept higher value ${fieldConflict.newValue}`);
              } else {
                resolvedData[fieldConflict.field] = fieldConflict.existingValue;
                resolutionLog.push(`Merged numeric field ${fieldConflict.field}: used existing higher value ${fieldConflict.existingValue}`);
              }
            }
            // For array fields, merge them
            else if (Array.isArray(fieldConflict.newValue) && Array.isArray(fieldConflict.existingValue)) {
              resolvedData[fieldConflict.field] = [...new Set([...fieldConflict.newValue, ...fieldConflict.existingValue])];
              resolutionLog.push(`Merged array field ${fieldConflict.field}: combined unique values`);
            }
            // For other fields, keep the newer value
            else {
              resolutionLog.push(`Kept newer value for field ${fieldConflict.field}: ${fieldConflict.newValue}`);
            }
          });
        }
      });
      break;

    case 'manual':
      // Flag for manual resolution
      resolutionLog.push('Conflict flagged for manual resolution');
      resolvedData.requiresManualResolution = true;
      resolvedData.conflicts = conflicts;
      break;

    default:
      resolutionLog.push(`Unknown conflict resolution strategy: ${conflictResolution}`);
  }
} else {
  resolutionLog.push('No conflicts detected - applying update directly');
}

// Prepare result
const syncResult = {
  updateId,
  dataType,
  entityId,
  originalData: syncData.updateData,
  resolvedData,
  conflicts,
  resolutionStrategy: conflictResolution,
  resolutionLog,
  status: conflicts.length > 0 && conflictResolution === 'manual' ? 'requires_manual_resolution' : 'resolved',
  timestamp: new Date().toISOString()
};

return { json: syncResult };

// Validate data integrity before broadcasting
const syncResult = $input.first().json;
const { updateId, dataType, entityId, resolvedData, conflicts } = syncResult;

const validationErrors = [];
const validationWarnings = [];

// Data type-specific validation
switch (dataType) {
  case 'character':
    // Validate character data
    if (resolvedData.hpCurrent !== undefined) {
      if (typeof resolvedData.hpCurrent !== 'number' || resolvedData.hpCurrent < 0) {
        validationErrors.push('Invalid HP value: must be non-negative number');
      }
      if (resolvedData.hpMax !== undefined && resolvedData.hpCurrent > resolvedData.hpMax) {
        validationWarnings.push('HP current exceeds HP max - capping at max value');
        resolvedData.hpCurrent = resolvedData.hpMax;
      }
    }

    if (resolvedData.level !== undefined) {
      if (typeof resolvedData.level !== 'number' || resolvedData.level < 1 || resolvedData.level > 100) {
        validationErrors.push('Invalid level: must be number between 1 and 100');
      }
    }
    break;

  case 'scene':
    // Validate scene data
    if (resolvedData.lighting) {
      const validLighting = ['bright', 'normal', 'dim', 'dark', 'magical', 'flickering'];
      if (!validLighting.includes(resolvedData.lighting)) {
        validationErrors.push(`Invalid lighting type: ${resolvedData.lighting}`);
      }
    }

    if (resolvedData.objects && !Array.isArray(resolvedData.objects)) {
      validationErrors.push('Scene objects must be an array');
    }
    break;

  case 'world':
    // Validate world data
    if (resolvedData.locations && !Array.isArray(resolvedData.locations)) {
      validationErrors.push('World locations must be an array');
    }

    if (resolvedData.npcs && !Array.isArray(resolvedData.npcs)) {
      validationErrors.push('World NPCs must be an array');
    }
    break;
}

// General validation
if (!entityId || typeof entityId !== 'string') {
  validationErrors.push('Invalid entity ID: must be non-empty string');
}

// Check for data structure integrity
if (typeof resolvedData !== 'object' || resolvedData === null) {
  validationErrors.push('Invalid data structure: must be object');
}

// Prepare validation result
const validationResult = {
  updateId,
  dataType,
  entityId,
  isValid: validationErrors.length === 0,
  validationErrors,
  validationWarnings,
  validatedData: resolvedData,
  requiresManualReview: validationErrors.length > 0,
  timestamp: new Date().toISOString()
};

return { json: validationResult };

// Prepare and broadcast validated sync update to all clients
const validationResult = $input.first().json;
const { updateId, dataType, entityId, isValid, validatedData, validationErrors, validationWarnings } = validationResult;

if (!isValid) {
  return {
    json: {
      type: 'sync_error',
      data: {
        updateId,
        dataType,
        entityId,
        errors: validationErrors,
        warnings: validationWarnings,
        status: 'validation_failed'
      },
      channels: ['sync_errors', 'dm_updates'],
      timestamp: new Date().toISOString()
    }
  };
}

// Prepare broadcast payload
const broadcastPayload = {
  type: 'sync_update',
  data: {
    updateId,
    dataType,
    entityId,
    updateData: validatedData,
    validationWarnings: validationWarnings.length > 0 ? validationWarnings : undefined,
    status: 'synced'
  },
  channels: [
    `${dataType}_updates`,
    `${dataType}_${entityId}`,
    'game_updates',
    'sync_broadcast'
  ],
  timestamp: new Date().toISOString()
};

return { json: broadcastPayload };

// Send WebSocket broadcast to all connected clients
const broadcastData = $input.first().json;

// Send to WebSocket system
const response = await fetch('http://localhost:5678/webhook/websocket/broadcast', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(broadcastData)
});

let broadcastResult;
if (response.ok) {
  broadcastResult = {
    success: true,
    broadcastId: `broadcast_${Date.now()}`,
    channels: broadcastData.channels,
    recipients: 'all_connected_clients'
  };
} else {
  broadcastResult = {
    success: false,
    error: `Broadcast failed: ${response.statusText}`,
    status: response.status
  };
}

return { json: { broadcast: broadcastResult, originalData: broadcastData } };

