// Process rollback request
const rollbackData = $input.first().json;
const { 
  updateId,
  sessionId,
  reason = 'manual_rollback',
  rollbackTo = null // timestamp or updateId to rollback to
} = rollbackData;

// Validate required fields
if (!updateId || !sessionId) {
  throw new Error('Missing required fields: updateId, sessionId');
}

// Prepare rollback operation
const rollbackOperation = {
  rollbackId: `rollback_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  originalUpdateId: updateId,
  sessionId,
  reason,
  rollbackTo,
  timestamp: new Date().toISOString(),
  status: 'pending'
};

return { json: rollbackOperation };

// Execute rollback and restore previous state
const rollbackData = $input.first().json;
const { rollbackId, originalUpdateId, rollbackTo, reason } = rollbackData;

// Get sync history to find rollback target
let history = [];
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  history = $input[1].json.values.map(row => ({
    updateId: row[0],
    dataType: row[1],
    entityId: row[2],
    updateData: JSON.parse(row[3] || '{}'),
    timestamp: row[4],
    clientId: row[5],
    sessionId: row[6]
  }));
}

// Find the original update
const originalUpdate = history.find(h => h.updateId === originalUpdateId);
if (!originalUpdate) {
  throw new Error(`Original update not found: ${originalUpdateId}`);
}

// Find rollback target
let rollbackTarget = null;
if (rollbackTo) {
  // Rollback to specific update or timestamp
  rollbackTarget = history.find(h => 
    h.updateId === rollbackTo || h.timestamp === rollbackTo
  );
} else {
  // Find the most recent update before the original
  const earlierUpdates = history.filter(h => 
    new Date(h.timestamp) < new Date(originalUpdate.timestamp) &&
    h.dataType === originalUpdate.dataType &&
    h.entityId === originalUpdate.entityId
  );

  if (earlierUpdates.length > 0) {
    rollbackTarget = earlierUpdates.reduce((latest, current) => 
      new Date(current.timestamp) > new Date(latest.timestamp) ? current : latest
    );
  }
}

if (!rollbackTarget) {
  throw new Error('No suitable rollback target found');
}

// Prepare rollback data
const rollbackResult = {
  rollbackId,
  originalUpdateId,
  rollbackTargetId: rollbackTarget.updateId,
  dataType: originalUpdate.dataType,
  entityId: originalUpdate.entityId,
  restoredData: rollbackTarget.updateData,
  originalData: originalUpdate.updateData,
  reason,
  rollbackTimestamp: new Date().toISOString(),
  originalTimestamp: originalUpdate.timestamp,
  restoredTimestamp: rollbackTarget.timestamp
};

return { json: rollbackResult };

// Broadcast rollback notification to all clients
const rollbackData = $input.first().json;

const rollbackBroadcast = {
  type: 'sync_rollback',
  data: {
    rollbackId: rollbackData.rollbackId,
    originalUpdateId: rollbackData.originalUpdateId,
    dataType: rollbackData.dataType,
    entityId: rollbackData.entityId,
    restoredData: rollbackData.restoredData,
    reason: rollbackData.reason,
    rollbackTimestamp: rollbackData.rollbackTimestamp
  },
  channels: [
    `${rollbackData.dataType}_updates`,
    `${rollbackData.dataType}_${rollbackData.entityId}`,
    'game_updates',
    'rollback_notifications'
  ],
  timestamp: new Date().toISOString()
};

// Send to WebSocket system
fetch('http://localhost:5678/webhook/websocket/broadcast', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(rollbackBroadcast)
}).catch(error => {
  console.error('Failed to broadcast rollback:', error);
});

return { json: rollbackBroadcast };

