// Generate audit trail for sync operations
const auditRequest = $input.first().json;
const { 
  sessionId,
  clientId,
  timeRange = '24h', // '1h', '24h', '7d', '30d'
  dataType = null,
  entityId = null
} = auditRequest;

// Validate required fields
if (!sessionId) {
  throw new Error('Missing required field: sessionId');
}

// Prepare audit query
const auditQuery = {
  sessionId,
  clientId,
  timeRange,
  dataType,
  entityId,
  requestedAt: new Date().toISOString()
};

return { json: auditQuery };

// Generate comprehensive audit report
const auditQuery = $input.first().json;
const { sessionId, timeRange, dataType, entityId } = auditQuery;

// Get all sync history
let allHistory = [];
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  allHistory = $input[1].json.values.map(row => ({
    updateId: row[0],
    dataType: row[1],
    entityId: row[2],
    updateData: JSON.parse(row[3] || '{}'),
    timestamp: row[4],
    clientId: row[5],
    sessionId: row[6],
    status: row[7]
  }));
}

// Calculate time range filter
const now = new Date();
let timeLimit;
switch (timeRange) {
  case '1h':
    timeLimit = new Date(now.getTime() - 60 * 60 * 1000);
    break;
  case '24h':
    timeLimit = new Date(now.getTime() - 24 * 60 * 60 * 1000);
    break;
  case '7d':
    timeLimit = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    break;
  case '30d':
    timeLimit = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    break;
  default:
    timeLimit = new Date(now.getTime() - 24 * 60 * 60 * 1000);
}

// Filter audit data
const filteredHistory = allHistory.filter(entry => {
  const entryTime = new Date(entry.timestamp);
  return (
    entry.sessionId === sessionId &&
    entryTime >= timeLimit &&
    (!dataType || entry.dataType === dataType) &&
    (!entityId || entry.entityId === entityId)
  );
});

// Generate audit statistics
const auditStats = {
  totalUpdates: filteredHistory.length,
  successfulUpdates: filteredHistory.filter(e => e.status === 'resolved').length,
  failedUpdates: filteredHistory.filter(e => e.status === 'validation_failed').length,
  pendingUpdates: filteredHistory.filter(e => e.status === 'pending').length,
  dataTypes: [...new Set(filteredHistory.map(e => e.dataType))],
  entities: [...new Set(filteredHistory.map(e => e.entityId))],
  clients: [...new Set(filteredHistory.map(e => e.clientId))],
  timeRange: timeRange,
  generatedAt: new Date().toISOString()
};

// Group updates by hour for timeline
const timelineData = {};
filteredHistory.forEach(entry => {
  const hour = new Date(entry.timestamp).toISOString().slice(0, 13); // YYYY-MM-DDTHH
  if (!timelineData[hour]) {
    timelineData[hour] = { total: 0, successful: 0, failed: 0 };
  }
  timelineData[hour].total++;
  if (entry.status === 'resolved') timelineData[hour].successful++;
  if (entry.status === 'validation_failed') timelineData[hour].failed++;
});

// Prepare audit report
const auditReport = {
  sessionId,
  query: auditQuery,
  statistics: auditStats,
  timeline: Object.entries(timelineData).map(([hour, data]) => ({
    hour,
    ...data
  })).sort((a, b) => a.hour.localeCompare(b.hour)),
  updates: filteredHistory.map(entry => ({
    updateId: entry.updateId,
    dataType: entry.dataType,
    entityId: entry.entityId,
    timestamp: entry.timestamp,
    clientId: entry.clientId,
    status: entry.status,
    dataSummary: Object.keys(entry.updateData).length
  })),
  generatedAt: new Date().toISOString()
};

return { json: auditReport };
